for (let i = 0; i < N; i++) p[i] = Number(data[pos++]);

const C = Number(data[pos++]);

const perType = new Array(T + 1);
for (let i = 0; i < N; i++) {
    const ty = t[i];
    if (perType[ty] === undefined) perType[ty] = [];
    perType[ty].push(i);
}

for (let ty = 1; ty <= T; ty++) {
    const arr = perType[ty];
    if (arr !== undefined && arr.length > 1) {
        arr.sort((a, b) => p[a] - p[b] || a - b);
    }
}

