global.sort((a, b) => p[a] - p[b] || t[a] - t[b] || a - b);

const sold = new Uint8Array(N);
const ptr = new Int32Array(T + 1);

let globalPtr = 0;
let revenue = 0;

for (let j = 0; j < C; j++) {
    const u = Number(data[pos++]);

    if (u === 0) {
        while (globalPtr < N && sold[global[globalPtr]]) globalPtr++;

        if (globalPtr < N) {
            const id = global[globalPtr++];
            sold[id] = 1;
            revenue += p[id];
        }
    } else {
        const arr = perType[u];

        if (arr !== undefined) {
            let k = ptr[u];

            while (k < arr.length && sold[arr[k]]) k++;
            ptr[u] = k;

            if (k < arr.length) {
                const id = arr[k];
                sold[id] = 1;
                revenue += p[id];
                ptr[u] = k + 1;
            }
        }
    }
}

console.log(revenue);
